// Normaliza el cuerpo. Cada canal manda lo suyo: WhatsApp trae el telefono en
// `contacto`, y el agente de voz puede no traer email porque el reconocimiento
// lo destroza. Lo que sale de aqui es lo unico que ve el resto del workflow.
const body = $json.body || $json || {};
const clientId = String(body.client_id || '').trim();

// Los servicios pueden llegar como lista o como una sola cadena: la IA devuelve
// lo que le sale, y aqui se deja siempre como lista.
let servicios = body.servicios || body.servicio || [];
if (!Array.isArray(servicios)) servicios = servicios ? [String(servicios)] : [];
servicios = servicios.map((s) => String(s || '').trim()).filter(Boolean);

// Cuanto pasado y cuanto futuro hay que cargar de la base.
//
// Lo normal son nueve dias. Pero desde que se puede pedir cita a dos meses
// vista, si alguien nombra una fecha lejana hay que traerse las citas de ESE
// dia: sin ellas el motor lo veria vacio y contestaria que esta libre una hora
// que ya tiene a alguien. La reserva no llegaria a duplicarse --la restriccion
// de la base lo impide-- pero la persona se iria con un "si, esta libre"
// seguido de un "pues ya no", que es la peor conversacion posible.
const ahora = new Date();
const desde = new Date(ahora.getTime() - 2 * 3600 * 1000);
let hasta = new Date(ahora.getTime() + 9 * 86400000);

if (/^\d{4}-\d{2}-\d{2}$/.test(String(body.fecha || ''))) {
  const finDelDia = new Date(body.fecha + 'T23:59:59Z');
  // Con tope: una fecha disparatada por un error de tecleo no puede hacer que
  // cada mensaje se traiga anios de agenda.
  const tope = new Date(ahora.getTime() + 120 * 86400000);
  if (finDelDia > hasta) hasta = finDelDia < tope ? finDelDia : tope;
}

return [{
  json: {
    client_id: clientId,
    // La ventana de datos, ya resuelta: los nodos que la usan no tienen que
    // repetir este calculo en una expresion.
    desde: desde.toISOString(),
    hasta: hasta.toISOString(),
    // Sin un uuid valido no tiene sentido consultar Supabase: la query
    // devolveria 'invalid input syntax for type uuid' y la ejecucion fallaria.
    cliente_valido: /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(clientId),
    accion: String(body.accion || 'disponibilidad').trim().toLowerCase(),
    // Igual que reservar, mover se hace en dos pasos: primero se mira si esa
    // hora esta libre y se ofrece, y solo cuando la persona dice que si se
    // toca la cita. Preguntar no es pedir, tambien para un cambio.
    confirmar: body.confirmar === true,
    fecha: body.fecha || null,
    hora: body.hora || null,
    email: body.email || null,
    contacto: String(body.contacto || '').trim(),
    nombre: String(body.nombre || '').trim(),
    // Que se quiere hacer, y con quien. Los dos son texto libre: el motor los
    // empareja contra el catalogo real del negocio.
    servicios: servicios,
    trabajador: String(body.trabajador || '').trim(),
    // La frase tal cual la ha escrito la persona. Es una PISTA para deducir el
    // servicio cuando nadie lo ha dicho aun, y el motor solo la mira si no
    // venia un servicio explicito. El bot la necesita porque ensena huecos
    // antes de que la IA conteste, y ahi lo unico que hay es la frase.
    texto: String(body.texto || '').trim(),
    motivo: String(body.motivo || '').trim(),
    canal: String(body.canal || 'whatsapp').trim(),
    conversation_id: body.conversation_id || null,
  },
}];

return [{
  json: {
    ok: false,
    motivo: 'cliente_desconocido',
    mensaje: 'No encuentro la configuracion de este negocio. Avisa al administrador.',
  },
}];

